package com.cyancoder.tenant.model;
import jakarta.persistence.*;import java.time.Instant;
@Entity@Table(name="tenant_invitations",indexes={@Index(name="idx_tenant_invitation_scope",columnList="tenant_key,created_at")})public class TenantInvitationEntity{@Id@Column(name="invitation_id",length=64)private String invitationId;@Column(name="tenant_key",nullable=false,length=80)private String tenantKey;@Column(nullable=false,length=240)private String email;@Column(name="role_key",nullable=false,length=64)private String roleKey;@Column(name="token_hash",nullable=false,unique=true,length=64)private String tokenHash;@Column(nullable=false,length=24)private String status;@Column(name="delivery_status",nullable=false,length=32)private String deliveryStatus;@Column(name="created_by",nullable=false,length=180)private String createdBy;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="expires_at",nullable=false)private Instant expiresAt;@Column(name="accepted_at")private Instant acceptedAt;public String getInvitationId(){return invitationId;}public void setInvitationId(String v){invitationId=v;}public String getTenantKey(){return tenantKey;}public void setTenantKey(String v){tenantKey=v;}public String getEmail(){return email;}public void setEmail(String v){email=v;}public String getRoleKey(){return roleKey;}public void setRoleKey(String v){roleKey=v;}public String getTokenHash(){return tokenHash;}public void setTokenHash(String v){tokenHash=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public String getDeliveryStatus(){return deliveryStatus;}public void setDeliveryStatus(String v){deliveryStatus=v;}public String getCreatedBy(){return createdBy;}public void setCreatedBy(String v){createdBy=v;}public Instant getCreatedAt(){return createdAt;}public void setCreatedAt(Instant v){createdAt=v;}public Instant getExpiresAt(){return expiresAt;}public void setExpiresAt(Instant v){expiresAt=v;}public Instant getAcceptedAt(){return acceptedAt;}public void setAcceptedAt(Instant v){acceptedAt=v;}}
